1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"sort"
7		"sync"
8	)
9	
10	// deviceInput is one member of a create-pool request.
11	type deviceInput struct {
12		ID            string `json:"id"`
13		CapacityBytes int64  `json:"capacityBytes"`
14		FaultDomain   string `json:"faultDomain"`
15	}
16	
17	type createPoolInput struct {
18		ID      string        `json:"id"`
19		Devices []deviceInput `json:"devices"`
20	}
21	
22	type reservationInput struct {
23		RequestID string `json:"requestId"`
24		Bytes     int64  `json:"bytes"`
25	}
26	
27	// deviceView is the public representation of a pool device.
28	type deviceView struct {
29		ID            string `json:"id"`
30		CapacityBytes int64  `json:"capacityBytes"`
31		FaultDomain   string `json:"faultDomain"`
32	}
33	
34	// poolView is the public representation of a storage pool.
35	type poolView struct {
36		ID               string       `json:"id"`
37		Devices          []deviceView `json:"devices"`
38		RawCapacityBytes int64        `json:"rawCapacityBytes"`
39		AllocatedBytes   int64        `json:"allocatedBytes"`
40		AvailableBytes   int64        `json:"availableBytes"`
41	}
42	
43	// reservationView is the result of a successful reservation request.
44	type reservationView struct {
45		PoolID    string `json:"poolId"`
46		RequestID string `json:"requestId"`
47		Bytes     int64  `json:"bytes"`
48	}
49	
50	type reservation struct {
51		requestID string
52		bytes     int64
53		tenant    string
54	}
55	
56	// pool is one storage pool. tenantUsed tracks each tenant's charged bytes
57	// (reservations + volumes + snapshots + objects) inside the pool; quotas maps
58	// a tenant id to its byte limit. Tenants without a quota entry are unlimited.
59	type pool struct {
60		id            string
61		devices       []deviceInput
62		rawCapacity   int64
63		reservations  map[string]reservation
64		volumeBytes   int64 // total sizeBytes of volumes in this pool
65		snapshotBytes int64 // total sizeBytes of snapshots held in this pool
66		objectBytes   int64 // total sizeBytes of objects in buckets of this pool
67		tenantUsed    map[string]int64
68		quotas        map[string]int64
69	}
70	
71	// volume is a capacity allocation inside a pool with an optional exclusive
72	// node binding. generation is bumped on every binding state change.
73	// cloneSource records the snapshot a volume was cloned from ("" for a volume
74	// created directly) so clone retries can be told apart from foreign ids.
75	// tenant is the owning tenant; its sizeBytes is charged to the tenant's usage
76	// in the pool.
77	type volume struct {
78		id          string
79		poolID      string
80		sizeBytes   int64
81		generation  int64
82		binding     string // "" when unbound
83		cloneSource string // snapshot id when produced via a clone
84		tenant      string
85	}
86	
87	func (p *pool) allocated() int64 {
88		var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
89		for _, r := range p.reservations {
90			total += r.bytes
91		}
92		return total
93	}
94	
95	func (p *pool) view() poolView {
96		devices := make([]deviceView, len(p.devices))
97		for i, d := range p.devices {
98			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
99		}
100		allocated := p.allocated()
101		return poolView{
102			ID:               p.id,
103			Devices:          devices,
104			RawCapacityBytes: p.rawCapacity,
105			AllocatedBytes:   allocated,
106			AvailableBytes:   p.rawCapacity - allocated,
107		}
108	}
109	
110	// store is the in-memory state of the service. It is wiped on restart.
111	type store struct {
112		mu          sync.RWMutex
113		pools       map[string]*pool
114		volumes     map[string]*volume
115		snapshots   map[string]*snapshot
116		buckets     map[string]*bucket
117		deviceOwner map[string]string
118		// auditEvents is the append-only audit log; auditSeq is the sequence of
119		// its last entry (0 while empty). Both are mutated under mu, together with
120		// the business state each event describes.
121		auditEvents []auditEvent
122		auditSeq    int64
123	}
124	
125	func newStore() *store {
126		return &store{
127			pools:       make(map[string]*pool),
128			volumes:     make(map[string]*volume),
129			snapshots:   make(map[string]*snapshot),
130			buckets:     make(map[string]*bucket),
131			deviceOwner: make(map[string]string),
132		}
133	}
134	
135	func validID(id string) bool {
136		return idPattern.MatchString(id)
137	}
138	
139	func (s *store) listPools(w http.ResponseWriter) {
140		s.mu.RLock()
141		ids := make([]string, 0, len(s.pools))
142		for id := range s.pools {
143			ids = append(ids, id)
144		}
145		sort.Strings(ids)
146		items := make([]poolView, 0, len(ids))
147		for _, id := range ids {
148			items = append(items, s.pools[id].view())
149		}
150		s.mu.RUnlock()
151		writeJSON(w, http.StatusOK, map[string]any{"items": items})
152	}
153	
154	func (s *store) getPool(w http.ResponseWriter, id string) {
155		if !validID(id) {
156			writeError(w, http.StatusBadRequest, "invalid_request")
157			return
158		}
159		s.mu.RLock()
160		p, ok := s.pools[id]
161		var v poolView
162		if ok {
163			v = p.view()
164		}
165		s.mu.RUnlock()
166		if !ok {
167			writeError(w, http.StatusNotFound, "pool_not_found")
168			return
169		}
170		writeJSON(w, http.StatusOK, v)
171	}
172	
173	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
174		var in createPoolInput
175		if !decodeRequest(r, &in) {
176			writeError(w, http.StatusBadRequest, "invalid_request")
177			return
178		}
179		// Validate the whole payload before touching any state so a failure
180		// never leaves a partial pool behind.
181		if !validID(in.ID) || len(in.Devices) == 0 {
182			writeError(w, http.StatusBadRequest, "invalid_request")
183			return
184		}
185		seen := make(map[string]bool, len(in.Devices))
186		var rawCapacity int64
187		for _, d := range in.Devices {
188			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
189				writeError(w, http.StatusBadRequest, "invalid_request")
190				return
191			}
192			if rawCapacity > math.MaxInt64-d.CapacityBytes {
193				writeError(w, http.StatusBadRequest, "invalid_request")
194				return
195			}
196			seen[d.ID] = true
197			rawCapacity += d.CapacityBytes
198		}
199	
200		s.mu.Lock()
201		defer s.mu.Unlock()
202		if _, ok := s.pools[in.ID]; ok {
203			writeError(w, http.StatusConflict, "pool_exists")
204			return
205		}
206		for _, d := range in.Devices {
207			if _, busy := s.deviceOwner[d.ID]; busy {
208				writeError(w, http.StatusConflict, "device_in_use")
209				return
210			}
211		}
212	
213		devices := append([]deviceInput(nil), in.Devices...)
214		p := &pool{
215			id:           in.ID,
216			devices:      devices,
217			rawCapacity:  rawCapacity,
218			reservations: make(map[string]reservation),
219			tenantUsed:   make(map[string]int64),
220			quotas:       make(map[string]int64),
221		}
222		s.pools[in.ID] = p
223		for _, d := range devices {
224			s.deviceOwner[d.ID] = in.ID
225		}
226		s.appendAudit(auditPoolCreated, storagePoolPath+"/"+in.ID, in.ID, 0)
227		writeJSON(w, http.StatusCreated, p.view())
228	}
229	
230	func (s *store) deletePool(w http.ResponseWriter, id string) {
231		if !validID(id) {
232			writeError(w, http.StatusBadRequest, "invalid_request")
233			return
234		}
235		s.mu.Lock()
236		defer s.mu.Unlock()
237		p, ok := s.pools[id]
238		if !ok {
239			writeError(w, http.StatusNotFound, "pool_not_found")
240			return
241		}
242		if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
243			writeError(w, http.StatusConflict, "pool_not_empty")
244			return
245		}
246		// An empty bucket still blocks pool deletion even though it charges no
247		// bytes.
248		for _, b := range s.buckets {
249			if b.poolID == id {
250				writeError(w, http.StatusConflict, "pool_not_empty")
251				return
252			}
253		}
254		for _, d := range p.devices {
255			delete(s.deviceOwner, d.ID)
256		}
257		delete(s.pools, id)
258		s.appendAudit(auditPoolDeleted, storagePoolPath+"/"+id, id, 0)
259		w.WriteHeader(http.StatusNoContent)
260	}
261	
262	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
263		var in reservationInput
264		if !decodeRequest(r, &in) {
265			writeError(w, http.StatusBadRequest, "invalid_request")
266			return
267		}
268		tenant, tok := extractTenant(r.Header)
269		if !tok || !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
270			writeError(w, http.StatusBadRequest, "invalid_request")
271			return
272		}
273	
274		s.mu.Lock()
275		defer s.mu.Unlock()
276		p, ok := s.pools[poolID]
277		if !ok {
278			writeError(w, http.StatusNotFound, "pool_not_found")
279			return
280		}
281		if existing, dup := p.reservations[in.RequestID]; dup {
282			if existing.bytes != in.Bytes || existing.tenant != tenant {
283				writeError(w, http.StatusConflict, "idempotency_conflict")
284				return
285			}
286			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
287			return
288		}
289		// Holding the store lock makes the quota and capacity checks plus the
290		// charge atomic, so concurrent creates can never exceed either limit.
291		if p.tenantQuotaExceeded(tenant, in.Bytes) {
292			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
293			return
294		}
295		allocated := p.allocated()
296		if allocated > p.rawCapacity-in.Bytes {
297			writeError(w, http.StatusConflict, "insufficient_capacity")
298			return
299		}
300		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes, tenant: tenant}
301		p.tenantUsed[tenant] += in.Bytes
302		s.appendAudit(auditReservationCreated,
303			storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
304		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
305	}
306	
307	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
308		if !validID(poolID) || !validID(requestID) {
309			writeError(w, http.StatusBadRequest, "invalid_request")
310			return
311		}
312		s.mu.Lock()
313		defer s.mu.Unlock()
314		p, ok := s.pools[poolID]
315		if !ok {
316			writeError(w, http.StatusNotFound, "pool_not_found")
317			return
318		}
319		// Deleting an unknown or already-deleted reservation is a success with
320		// no state change, so only a real deletion records an event.
321		if r, existed := p.reservations[requestID]; existed {
322			delete(p.reservations, requestID)
323			p.tenantUsed[r.tenant] -= r.bytes
324			s.appendAudit(auditReservationDeleted,
325				storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
326		}
327		w.WriteHeader(http.StatusNoContent)
328	}
