250		if !exists {
251			writeError(w, http.StatusNotFound, "volume_not_found")
252			return
253		}
254		if v.generation != gen {
255			writeError(w, http.StatusConflict, "stale_generation")
256			return
257		}
258		wasBound := v.binding != ""
259		v.binding = ""
260		if wasBound {
261			v.generation++
262			// Unbinding an already-unbound volume is a successful no-op: no
263			// generation bump and no audit event.
