269	// parseGenerationQuery accepts exactly one "expectedGeneration=<non-neg-int>"
270	// pair. Missing, empty, duplicated or extra parameters yield ok=false.
271	func parseGenerationQuery(raw string) (int64, bool) {
272		if raw == "" {
273			return 0, false
274		}
275		var gen int64
276		found := false
277		for _, pair := range strings.Split(raw, "&") {
278			key, value, ok := strings.Cut(pair, "=")
279			if !ok {
280				return 0, false
281			}
282			decodedKey, err := url.QueryUnescape(key)
283			if err != nil {
284				return 0, false
285			}
286			if decodedKey != "expectedGeneration" {
287				return 0, false
288			}
289			if found {
290				return 0, false
291			}
292			decodedValue, err := url.QueryUnescape(value)
293			if err != nil {
294				return 0, false
295			}
296			parsed, err := strconv.ParseInt(decodedValue, 10, 64)
297			if err != nil || parsed < 0 {
298				return 0, false
299			}
300			gen, found = parsed, true
301		}
302		return gen, found
303	}
