75	func (o *object) view() objectView {
76		return objectView{Key: o.key, SizeBytes: o.sizeBytes, Metadata: o.metadata, ETag: o.etag}
77	}
78	
79	// routeBuckets dispatches /v1/buckets and its sub-paths. The object key is
80	// the remainder of the path after "objects/" (already URL-decoded once by
81	// the net/http layer) and may contain slashes, so it is not split here.
82	func (s *store) routeBuckets(w http.ResponseWriter, r *http.Request) {
83		rest := strings.TrimPrefix(r.URL.Path, bucketPath)
84		if rest == "" {
85			switch r.Method {
86			case http.MethodGet:
87				s.listBuckets(w)
88			case http.MethodPost:
89				s.createBucket(w, r)
90			default:
91				methodNotAllowed(w, http.MethodGet, http.MethodPost)
92			}
93			return
94		}
95		// rest begins with "/"; the bucket id is the single next segment.
96		bucketID, tail, found := strings.Cut(rest[1:], "/")
97		if bucketID == "" {
98			writeError(w, http.StatusNotFound, "not_found")
99			return
100		}
101		if !found {
102			switch r.Method {
103			case http.MethodGet:
104				s.getBucket(w, bucketID)
105			case http.MethodDelete:
106				s.deleteBucket(w, bucketID)
107			default:
108				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
109			}
110			return
111		}
112		if tail == "objects" {
113			if r.Method != http.MethodGet {
114				methodNotAllowed(w, http.MethodGet)
115				return
116			}
117			s.listObjects(w, r, bucketID)
118			return
119		}
120		if key, ok := strings.CutPrefix(tail, "objects/"); ok {
121			switch r.Method {
122			case http.MethodPut:
123				s.putObject(w, r, bucketID, key)
124			case http.MethodGet:
125				s.getObject(w, r, bucketID, key, false)
126			case http.MethodHead:
127				s.getObject(w, r, bucketID, key, true)
128			case http.MethodDelete:
129				s.deleteObject(w, r, bucketID, key)
130			default:
131				methodNotAllowed(w, http.MethodPut, http.MethodGet, http.MethodHead, http.MethodDelete)
132			}
133			return
134		}
135		writeError(w, http.StatusNotFound, "not_found")
136	}
137	
138	func (s *store) listBuckets(w http.ResponseWriter) {
139		s.mu.RLock()
140		ids := make([]string, 0, len(s.buckets))
141		for id := range s.buckets {
142			ids = append(ids, id)
143		}
144		sort.Strings(ids)
145		items := make([]bucketView, 0, len(ids))
146		for _, id := range ids {
147			items = append(items, s.buckets[id].view())
148		}
149		s.mu.RUnlock()
150		writeJSON(w, http.StatusOK, map[string]any{"items": items})
151	}
152	
153	func (s *store) getBucket(w http.ResponseWriter, id string) {
154		if !validID(id) {
155			writeError(w, http.StatusBadRequest, "invalid_request")
156			return
157		}
158		s.mu.RLock()
159		b, ok := s.buckets[id]
160		var v bucketView
161		if ok {
162			v = b.view()
163		}
164		s.mu.RUnlock()
165		if !ok {
166			writeError(w, http.StatusNotFound, "bucket_not_found")
167			return
168		}
169		writeJSON(w, http.StatusOK, v)
170	}
171	
172	func (s *store) createBucket(w http.ResponseWriter, r *http.Request) {
173		var in createBucketInput
174		if !decodeRequest(r, &in) {
175			writeError(w, http.StatusBadRequest, "invalid_request")
176			return
177		}
178		tenant, tok := extractTenant(r.Header)
179		if !tok || !validID(in.ID) || !validID(in.PoolID) {
180			writeError(w, http.StatusBadRequest, "invalid_request")
181			return
182		}
183	
184		s.mu.Lock()
185		defer s.mu.Unlock()
186		if existing, dup := s.buckets[in.ID]; dup {
187			if existing.poolID == in.PoolID && existing.tenant == tenant {
188				writeJSON(w, http.StatusOK, existing.view())
189				return
190			}
191			writeError(w, http.StatusConflict, "bucket_exists")
192			return
193		}
194		if _, ok := s.pools[in.PoolID]; !ok {
195			writeError(w, http.StatusNotFound, "pool_not_found")
196			return
197		}
198		s.buckets[in.ID] = &bucket{id: in.ID, poolID: in.PoolID, tenant: tenant, objects: make(map[string]*object)}
199		s.appendAudit(auditBucketCreated, bucketPath+"/"+in.ID, in.PoolID, 0)
200		writeJSON(w, http.StatusCreated, s.buckets[in.ID].view())
201	}
202	
203	func (s *store) deleteBucket(w http.ResponseWriter, id string) {
204		if !validID(id) {
205			writeError(w, http.StatusBadRequest, "invalid_request")
206			return
207		}
208		s.mu.Lock()
209		defer s.mu.Unlock()
210		b, ok := s.buckets[id]
211		if !ok {
212			writeError(w, http.StatusNotFound, "bucket_not_found")
213			return
214		}
215		if len(b.objects) > 0 {
216			writeError(w, http.StatusConflict, "bucket_not_empty")
217			return
218		}
219		delete(s.buckets, id)
220		s.appendAudit(auditBucketDeleted, bucketPath+"/"+id, b.poolID, 0)
221		w.WriteHeader(http.StatusNoContent)
222	}
223	
224	// validObjectKey reports whether key is 1..1024 bytes of valid UTF-8 with no
225	// control characters.
226	func validObjectKey(key string) bool {
227		if len(key) == 0 || len(key) > 1024 || !utf8.ValidString(key) {
228			return false
229		}
230		for _, r := range key {
231			if unicode.IsControl(r) {
232				return false
233			}
234		}
235		return true
236	}
237	
238	// extractMetadata collects the X-Vaultgrid-Meta-* request headers into a
239	// metadata map keyed by the suffix after the prefix. A header with an empty
240	// suffix or a value that is not valid UTF-8 or carries control characters
241	// makes the whole request invalid.
242	func extractMetadata(h http.Header) (map[string]string, bool) {
243		meta := make(map[string]string)
244		for name, values := range h {
245			suffix, ok := strings.CutPrefix(name, metaPrefix)
246			if !ok {
247				continue
248			}
249			if suffix == "" {
250				return nil, false
251			}
252			for _, v := range values {
253				if !utf8.ValidString(v) {
254					return nil, false
255				}
256				for _, r := range v {
257					if unicode.IsControl(r) {
258						return nil, false
259					}
260				}
261			}
262			meta[suffix] = strings.Join(values, ", ")
263		}
264		return meta, true
265	}
266	
267	// parsePrecondition validates the conditional-write headers. It returns the
268	// If-Match etag ("" when absent) and whether If-None-Match: * was given. ok
269	// is false when both headers are present or either has an unsupported form.
270	func parsePrecondition(h http.Header) (ifMatch string, ifNoneMatchStar, ok bool) {
271		matches, hasMatch := h["If-Match"]
272		noneMatches, hasNoneMatch := h["If-None-Match"]
273		if hasMatch && hasNoneMatch {
274			return "", false, false
275		}
276		if hasMatch {
277			if len(matches) != 1 || !isQuotedETag(matches[0]) {
278				return "", false, false
279			}
280			return matches[0], false, true
281		}
282		if hasNoneMatch {
283			if len(noneMatches) != 1 || noneMatches[0] != "*" {
284				return "", false, false
285			}
286			return "", true, true
287		}
288		return "", false, true
289	}
290	
291	// isQuotedETag reports whether v looks like a quoted hex etag, e.g.
292	// "9f86d081...". The content is not checked against any object here.
293	func isQuotedETag(v string) bool {
294		if len(v) < 2 || v[0] != '"' || v[len(v)-1] != '"' {
295			return false
296		}
297		inner := v[1 : len(v)-1]
298		if inner == "" {
299			return false
300		}
301		for _, c := range inner {
302			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
303				return false
304			}
305		}
306		return true
307	}
308	
309	func etagOf(content []byte) string {
310		sum := sha256.Sum256(content)
311		return `"` + hex.EncodeToString(sum[:]) + `"`
312	}
313	
314	func (s *store) putObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
315		if !validID(bucketID) || !validObjectKey(key) {
316			writeError(w, http.StatusBadRequest, "invalid_request")
317			return
318		}
319		if r.URL.RawQuery != "" {
320			writeError(w, http.StatusBadRequest, "invalid_request")
321			return
322		}
323		metadata, ok := extractMetadata(r.Header)
324		if !ok {
325			writeError(w, http.StatusBadRequest, "invalid_request")
326			return
327		}
328		ifMatch, ifNoneMatchStar, ok := parsePrecondition(r.Header)
329		if !ok {
330			writeError(w, http.StatusBadRequest, "invalid_request")
331			return
332		}
333		content, err := io.ReadAll(r.Body)
334		if err != nil {
335			writeError(w, http.StatusBadRequest, "invalid_request")
336			return
337		}
338		etag := etagOf(content)
339		size := int64(len(content))
340	
341		s.mu.Lock()
342		defer s.mu.Unlock()
343		b, ok := s.buckets[bucketID]
344		if !ok {
345			writeError(w, http.StatusNotFound, "bucket_not_found")
346			return
347		}
348		existing := b.objects[key]
349		if ifMatch != "" && (existing == nil || existing.etag != ifMatch) {
350			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
351			return
352		}
353		if ifNoneMatchStar && existing != nil {
354			writeError(w, http.StatusPreconditionFailed, "precondition_failed")
355			return
356		}
357		var oldSize int64
358		if existing != nil {
359			oldSize = existing.sizeBytes
360		}
361		p := s.pools[b.poolID]
362		// The store lock makes the quota and capacity checks plus the charge
363		// atomic, so concurrent writes can never exceed either limit, and a failed
364		// write leaves the old object and its metadata untouched. Objects inherit
365		// the bucket's tenant; only a growing write can breach the quota.
366		if delta := size - oldSize; delta > 0 && p.tenantQuotaExceeded(b.tenant, delta) {
367			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
368			return
369		}
370		if p.allocated() > p.rawCapacity-(size-oldSize) {
371			writeError(w, http.StatusConflict, "insufficient_capacity")
372			return
373		}
374		b.objects[key] = &object{key: key, content: content, metadata: metadata, etag: etag, sizeBytes: size}
375		p.objectBytes += size - oldSize
376		p.tenantUsed[b.tenant] += size - oldSize
377		// An overwrite is recorded even when the size delta is zero.
378		resource := bucketPath + "/" + bucketID + "/objects/" + key
379		if existing != nil {
380			s.appendAudit(auditObjectOverwritten, resource, b.poolID, size-oldSize)
381		} else {
382			s.appendAudit(auditObjectCreated, resource, b.poolID, size)
383		}
384		status := http.StatusCreated
385		if existing != nil {
386			status = http.StatusOK
387		}
388		w.Header().Set("ETag", etag)
389		writeJSON(w, status, b.objects[key].view())
390	}
391	
392	// getObject serves both GET and HEAD; headOnly suppresses the body.
393	func (s *store) getObject(w http.ResponseWriter, r *http.Request, bucketID, key string, headOnly bool) {
394		if !validID(bucketID) || !validObjectKey(key) {
395			writeError(w, http.StatusBadRequest, "invalid_request")
396			return
397		}
398		if r.URL.RawQuery != "" {
399			writeError(w, http.StatusBadRequest, "invalid_request")
400			return
401		}
402		s.mu.RLock()
403		b, ok := s.buckets[bucketID]
404		var o *object
405		if ok {
406			o = b.objects[key]
407		}
408		s.mu.RUnlock()
409		if !ok {
410			writeError(w, http.StatusNotFound, "bucket_not_found")
411			return
412		}
413		if o == nil {
414			writeError(w, http.StatusNotFound, "object_not_found")
415			return
416		}
417		for name, value := range o.metadata {
418			w.Header().Set(metaPrefix+name, value)
419		}
420		w.Header().Set("ETag", o.etag)
421		w.Header().Set("Content-Type", "application/octet-stream")
422		w.Header().Set("Content-Length", strconv.FormatInt(o.sizeBytes, 10))
423		w.WriteHeader(http.StatusOK)
424		if !headOnly {
425			_, _ = w.Write(o.content)
426		}
427	}
428	
429	func (s *store) deleteObject(w http.ResponseWriter, r *http.Request, bucketID, key string) {
430		if !validID(bucketID) || !validObjectKey(key) {
431			writeError(w, http.StatusBadRequest, "invalid_request")
432			return
433		}
434		if r.URL.RawQuery != "" {
435			writeError(w, http.StatusBadRequest, "invalid_request")
436			return
437		}
438		s.mu.Lock()
439		defer s.mu.Unlock()
440		b, ok := s.buckets[bucketID]
441		if !ok {
442			writeError(w, http.StatusNotFound, "bucket_not_found")
443			return
444		}
445		// Deleting an unknown or already-deleted object is a success with no
446		// state change, so only a real deletion records an event.
447		if o, exists := b.objects[key]; exists {
448			s.pools[b.poolID].objectBytes -= o.sizeBytes
449			s.pools[b.poolID].tenantUsed[b.tenant] -= o.sizeBytes
450			delete(b.objects, key)
451			s.appendAudit(auditObjectDeleted, bucketPath+"/"+bucketID+"/objects/"+key, b.poolID, -o.sizeBytes)
452		}
453		w.WriteHeader(http.StatusNoContent)
454	}
455	
456	// parsePrefixQuery accepts an empty query or exactly one "prefix=<value>"
457	// pair. Duplicated or unknown parameters yield ok=false.
458	func parsePrefixQuery(raw string) (string, bool) {
459		if raw == "" {
460			return "", true
461		}
462		var prefix string
463		found := false
464		for _, pair := range strings.Split(raw, "&") {
465			k, value, ok := strings.Cut(pair, "=")
466			if !ok {
467				return "", false
468			}
469			decodedKey, err := url.QueryUnescape(k)
470			if err != nil || decodedKey != "prefix" || found {
471				return "", false
472			}
473			decodedValue, err := url.QueryUnescape(value)
474			if err != nil {
475				return "", false
476			}
477			prefix, found = decodedValue, true
478		}
479		return prefix, found
480	}
481	
482	func (s *store) listObjects(w http.ResponseWriter, r *http.Request, bucketID string) {
483		prefix, ok := parsePrefixQuery(r.URL.RawQuery)
484		if !ok || !validID(bucketID) {
485			writeError(w, http.StatusBadRequest, "invalid_request")
486			return
487		}
488		s.mu.RLock()
489		b, ok := s.buckets[bucketID]
490		var items []objectView
491		if ok {
492			keys := make([]string, 0, len(b.objects))
493			for k := range b.objects {
494				keys = append(keys, k)
495			}
496			sort.Strings(keys)
497			items = make([]objectView, 0, len(keys))
498			for _, k := range keys {
499				if strings.HasPrefix(k, prefix) {
500					items = append(items, b.objects[k].view())
501				}
502			}
503		}
504		s.mu.RUnlock()
505		if !ok {
506			writeError(w, http.StatusNotFound, "bucket_not_found")
507			return
508		}
509		writeJSON(w, http.StatusOK, map[string]any{"items": items})
510	}
511

