18	//	 4 volume.created      pool-a /v1/volumes/vol-1                     200
19	//	 5 volume.bound        pool-a /v1/volumes/vol-1/binding               0
20	//	 6 volume.unbound      pool-a /v1/volumes/vol-1/binding               0
21	//	 7 snapshot.created    pool-a /v1/snapshots/snap-1                   200
22	//	 8 clone.created       pool-b /v1/volumes/vol-2                      200
23	//	 9 bucket.created      pool-a /v1/buckets/bucket-1                     0
24	//	10 object.created      pool-a /v1/buckets/bucket-1/objects/k           3
25	//	11 object.overwritten  pool-a .../objects/k (same size)                0
26	//	12 object.overwritten  pool-a .../objects/k (shrunk)                  -2
27	//	13 object.deleted      pool-a .../objects/k                            -1
28	//	14 bucket.deleted      pool-a /v1/buckets/bucket-1                     0
29	//	15 snapshot.deleted    pool-a /v1/snapshots/snap-1                  -200
30	//	16 volume.deleted      pool-a /v1/volumes/vol-1                      -200
31	//	17 volume.deleted      pool-b /v1/volumes/vol-2                      -200
32	//	18 reservation.deleted pool-a .../reservations/r1                   -100
33	//	19 pool.deleted        pool-a /v1/storage-pools/pool-a                 0
34	//	20 pool.deleted        pool-b /v1/storage-pools/pool-b                 0
35	func auditFixture(t *testing.T, h http.Handler) {
36		t.Helper()
37		createPool(t, h, poolA)
38		createPool(t, h, `{"id":"pool-b","devices":[{"id":"dev3","capacityBytes":800,"faultDomain":"rack1"}]}`)
39	
40		if rec := reserve(t, h, "pool-a", `{"requestId":"r1","bytes":100}`); rec.Code != http.StatusCreated {
41			t.Fatalf("reserve = %d %s", rec.Code, rec.Body.String())
42		}
