44			t.Fatalf("create volume = %d %s", rec.Code, rec.Body.String())
45		}
46	
47		// Failures and idempotent retries before the bind: no events.
48		if rec := do(h, http.MethodPost, "/v1/volumes", `{"id":"vol-1","poolId":"pool-a","sizeBytes":200}`); rec.Code != http.StatusOK {
49			t.Fatalf("volume idempotent retry = %d %s", rec.Code, rec.Body.String())
50		}
51		wantError(t, reserve(t, h, "pool-a", `{"requestId":"rX-big","bytes":2000}`), http.StatusConflict, "insufficient_capacity")
52		wantError(t, do(h, http.MethodPut, "/v1/volumes/vol-1/binding", `{"nodeId":"n","expectedGeneration":9}`), http.StatusConflict, "stale_generation")
53	
54		bind := `{"nodeId":"node-1","expectedGeneration":0}`
55		if rec := do(h, http.MethodPut, "/v1/volumes/vol-1/binding", bind); rec.Code != http.StatusOK {
