252		h := Handler()
253		auditFixture(t, h)
254		want := expectedAuditFixture()
255	
256		// Pages of 5 walk the whole log; hasMore is true until the final page.
257		v := getAuditEvents(t, h, "/v1/audit-events?limit=5")
