269			t.Fatalf("page 2 = %v", v)
270		}
271		for i := 0; i < 5; i++ {
272			checkEvent(t, page[i], want[5+i])
273		}
274	
275		// Final partial page: 5 items, hasMore false, nextAfter = last sequence.
276		v = getAuditEvents(t, h, "/v1/audit-events?after=15&limit=5")
277		page = v["items"].([]any)
278		if len(page) != 5 || v["hasMore"].(bool) || v["nextAfter"].(float64) != 20 {
279			t.Fatalf("final page = %v", v)
280		}
281		for i := 0; i < 5; i++ {
282			checkEvent(t, page[i], want[15+i])
283		}
284	
285		// after at the last sequence returns an empty page echoing after.
286		v = getAuditEvents(t, h, "/v1/audit-events?after=20")
287		items := v["items"].([]any)
