424	// TestAuditEventsConcurrentCommits hammers reservations while reading the
425	// log. Committed sequences must be dense from 1 with no duplicates or gaps,
426	// every page must be internally consistent, and the deltas must reconcile
427	// with the live capacity report.
428	func TestAuditEventsConcurrentCommits(t *testing.T) {
429		h := Handler()
430		createPool(t, h, `{"id":"cp","devices":[{"id":"d","capacityBytes":100000,"faultDomain":"fd"}]}`)
431	
432		const goroutines, iterations = 8, 40
433		var wg sync.WaitGroup
434		for i := 0; i < goroutines; i++ {
435			wg.Add(1)
436			go func(i int) {
437				defer wg.Done()
438				for j := 0; j < iterations; j++ {
439					id := fmt.Sprintf("r%d-%d", i, j)
440					rec := reserve(t, h, "cp", fmt.Sprintf(`{"requestId":%q,"bytes":1}`, id))
441					if rec.Code != http.StatusCreated {
442						t.Errorf("reserve = %d %s", rec.Code, rec.Body.String())
443						return
444					}
445					if rec := do(h, http.MethodDelete, "/v1/storage-pools/cp/reservations/"+id, ""); rec.Code != http.StatusNoContent {
446						t.Errorf("delete = %d", rec.Code)
447						return
448					}
449				}
450			}(i)
451		}
452	
453		// Readers race the writers above.
454		for i := 0; i < 100; i++ {
455			v := getAuditEvents(t, h, "/v1/audit-events?limit=1000")
456			items := v["items"].([]any)
457			var prev float64
458			for n, raw := range items {
459				seq := raw.(map[string]any)["sequence"].(float64)
460				if seq != prev+1 {
461					t.Fatalf("page item %d sequence %v follows %v (gap/dup)", n, seq, prev)
462				}
463				prev = seq
464			}
465			// nextAfter is the last item (or after=0 on an empty page).
466			if len(items) > 0 && v["nextAfter"] != prev {
467				t.Fatalf("nextAfter %v != last sequence %v", v["nextAfter"], prev)
468			}
469			if v["hasMore"].(bool) {
470				t.Fatalf("limit 1000 should cover all events, hasMore=true (page %d)", len(items))
471			}
472		}
473		wg.Wait()
474	
475		v := getAuditEvents(t, h, "/v1/audit-events?limit=1000")
476		items := v["items"].([]any)
477		if len(items) != 1+goroutines*iterations*2 {
478			t.Fatalf("event count = %d, want %d", len(items), 1+goroutines*iterations*2)
479		}
480		var created, deleted, sumDelta float64
481		for i, raw := range items {
482			e := raw.(map[string]any)
483			if e["sequence"].(float64) != float64(i+1) {
484				t.Fatalf("sequence gap at %d: %v", i, e["sequence"])
485			}
486			if e["poolId"] != "cp" {
487				t.Fatalf("unexpected poolId: %v", e["poolId"])
488			}
489			sumDelta += e["bytesDelta"].(float64)
490			switch e["action"] {
491			case "pool.created":
492				if i != 0 || e["bytesDelta"].(float64) != 0 {
493					t.Fatalf("unexpected first event: %v", e)
494				}
495			case "reservation.created":
496				if e["bytesDelta"].(float64) != 1 {
497					t.Fatalf("created delta = %v", e["bytesDelta"])
498				}
499				created++
500			case "reservation.deleted":
501				if e["bytesDelta"].(float64) != -1 {
502					t.Fatalf("deleted delta = %v", e["bytesDelta"])
503				}
504				deleted++
505			default:
506				t.Fatalf("unexpected action %q", e["action"])
507			}
508		}
509		if created != float64(goroutines*iterations) || deleted != created || sumDelta != 0 {
510			t.Fatalf("created %v deleted %v delta sum %v", created, deleted, sumDelta)
511		}
512	
513		// The audit deltas reconcile with the live capacity view.
514		report := getReport(t, h, "/v1/capacity-report?poolId=cp")
515		item := report["items"].([]any)[0].(map[string]any)
516		if item["allocatedBytes"].(float64) != 0 {
517			t.Fatalf("allocated = %v, want 0", item["allocatedBytes"])
518		}
519	}
520

