			return 0, false
		}
		decodedKey, err := url.QueryUnescape(key)
		if err != nil {
			return 0, false
		}
		if decodedKey != "expectedGeneration" {
			return 0, false
		}
		if found {
			return 0, false
		}
		decodedValue, err := url.QueryUnescape(value)
		if err != nil {
			return 0, false
		}
		parsed, err := strconv.ParseInt(decodedValue, 10, 64)
		if err != nil || parsed < 0 {
			return 0, false
		}
		gen, found = parsed, true
	}
	return gen, found
}

