		t.Fatalf("sizeBytes = %v", v["sizeBytes"])
	}
	if v["generation"].(float64) != 1 {
		t.Fatalf("generation = %v, want 1", v["generation"])
	}
	if binding, ok := v["binding"]; !ok || binding != nil {
		t.Fatalf("binding = %v, want null", binding)
	}

